class SemicolonTable:
    def __init__(self, txt: str):
        self.raw = txt
        self.rows = self._parse(txt)

    def _parse(self, txt: str):
        if not txt or txt.strip() == "":
            return []
        lines = [line.strip() for line in txt.strip().splitlines() if line.strip() != ""]
        rows = [ [cell.strip() for cell in line.split(';')] for line in lines ]
        return rows

    @property
    def row_count(self):
        return len(self.rows)

    @property
    def col_count(self):
        if not self.rows:
            return 0
        # assuming uniform column count: use max length of any row
        return max(len(r) for r in self.rows)

    def summary(self):
        if not self.rows:
            return "No data provided."
